                if (r, c) not in seen:
                    blocks.append((r, c))
                    seen.add((r, c))
    for r, c in blocks:
        coords = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c - 1), (r + 2, c + 2)]
        vals = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0 for rr, cc in coords]
        # Rotate the four corner colors clockwise.
        rotated = [vals[2], vals[0], vals[3], vals[1]]
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for (rr, cc), color, (dr, dc) in zip(coords, rotated, directions):
            if not (0 <= rr < h and 0 <= cc < w) or color == 0:
                continue
            i, j = rr, cc
            while 0 <= i < h and 0 <= j < w:
                out[i][j] = color
                i += dr
                j += dc
